166	static int AudioResampleSimple(int samplerate,int ch,short* pcmPtr,int* len )
167	{
168	    int retSamplerate = samplerate;
169	    int num  = 1;
170	    int i = 0,j= 0;
171	    int samplenum = *len >> 1;
172	    short *pcmPDtr = pcmPtr;
173	    short *pcmPStr = pcmPtr;
174	
175	    if(retSamplerate <= 48000)
176	    {
177	        return retSamplerate;
178	    }
179	
180	    samplenum /=ch;
181	    while(retSamplerate > 48000)
182	    {
183	        retSamplerate >>= 1;
184	        samplenum >>=1;
185	        num <<=1;
186	    }
187	
188	    num--;
189	    for(i=0;i<samplenum;i++)
190	    {
191	        for(j=0;j<ch;j++)
192	        {
193	            *pcmPStr++ = *pcmPDtr++;
194	        }
195	        pcmPDtr +=num*ch;
196	    }
197	
198	    *len = (samplenum<<1)*ch;
199	
200	    return retSamplerate;
201	}
