937	static uint32_t music_wav_duration(const char *path)
938	{
939	    FILE *fp;
940	    uint8_t hdr[44];
941	    uint32_t byte_rate, data_len;
942	
943	    fp = fopen(path, "rb");
944	    if (fp == NULL) return 0;
945	
946	    if (fread(hdr, 1, sizeof(hdr), fp) != sizeof(hdr))
947	    {
948	        fclose(fp);
949	        return 0;
950	    }
951	    fclose(fp);
952	
953	    if (memcmp(hdr, "RIFF", 4) != 0 || memcmp(hdr + 8, "WAVE", 4) != 0)
954	        return 0;
955	
956	    memcpy(&byte_rate, hdr + 28, 4);
957	    memcpy(&data_len, hdr + 40, 4);
958	    if (byte_rate == 0) return 0;
959	
960	    return data_len / byte_rate;
961	}
